{
  "success": true,
  "scrape_id": "01a14771-78f7-74b7-a998-1825d9dd9e1f",
  "data": {
    "alexandria": [
      {
        "provider": "firecrawl",
        "capability": "find-tools",
        "data": {
          "level": "tools",
          "items": [
            {
              "id": "github-com/repositories/repo",
              "provider": "github-com",
              "capability": "repositories/repo",
              "name": "Repo",
              "description": "One GitHub repository by owner/name or URL: stars, forks, watchers, open issue+PR count, creation/last-push dates, primary language, topics, license, default branch, homepage and flags (archived, fork, template). One request to GET /repos/{owner}/{name}; an unknown repository is an error.",
              "requiresOneOf": [
                [
                  "repo",
                  "url"
                ]
              ],
              "options": [
                {
                  "name": "repo",
                  "type": "string",
                  "in": "body",
                  "about": "Repository as `owner/name`, for example `firecrawl/firecrawl`. Provide exactly one of repo or url. Pattern: ^@?/?[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?/[A-Za-z0-9._-]{1,100}(?:\\.git)?/?$."
                },
                {
                  "name": "url",
                  "type": "string",
                  "in": "body",
                  "about": "HTTPS github.com/{owner}/{name} URL; deeper paths (issues, tree, ...) are accepted and reduced to the repository. Provide exactly one of repo or url. Pattern: ^(?:https?://)?(?:www\\.)?github\\.com/[A-Za-z0-9-]{1,39}/[A-Za-z0-9._-]{1,100}(?:[/?#].*)?$."
                }
              ],
              "response": {
                "about": "One GitHub repository by owner/name or URL: stars, forks, watchers, open issue+PR count, creation/last-push dates, primary language, topics, license, default branch, homepage and flags (archived, fork, template). One request to GET /repos/{owner}/{name}; an unknown repository is an error.",
                "key": "",
                "paginated": false,
                "fields": [
                  {
                    "name": "observed_at_ms",
                    "type": "number",
                    "about": "When the workflow read GitHub, Unix milliseconds."
                  },
                  {
                    "name": "repo",
                    "type": "string",
                    "about": "Normalized owner/name the call resolved to."
                  },
                  {
                    "name": "repository",
                    "type": "object"
                  },
                  {
                    "name": "source_url",
                    "type": "string",
                    "about": "The github.com page a human would read for the same answer."

